//! Same-connection conflict capture sequence, platform retains exact typed SQL.
#[derive(Debug,PartialEq,Eq)]pub enum Error<E>{Callback(E)}
pub trait Backend{type Error;fn ready(&mut self)->Result<(),Self::Error>;fn matches(&mut self)->Result<bool,Self::Error>;fn latest(&mut self)->Result<(),Self::Error>;fn write(&mut self)->Result<(),Self::Error>;}
pub fn execute<B:Backend>(b:&mut B)->Result<bool,Error<B::Error>>{b.ready().map_err(Error::Callback)?;if !b.matches().map_err(Error::Callback)?{return Ok(false)}b.latest().map_err(Error::Callback)?;b.write().map_err(Error::Callback)?;Ok(true)}
#[cfg(test)]mod tests{use super::*;struct Probe{trace:Vec<&'static str>,cut:usize,matched:bool}impl Probe{fn hit(&mut self,name:&'static str)->Result<(),usize>{self.trace.push(name);if self.trace.len()==self.cut{Err(self.cut)}else{Ok(())}}}impl Backend for Probe{type Error=usize;fn ready(&mut self)->Result<(),usize>{self.hit("ready")}fn matches(&mut self)->Result<bool,usize>{self.hit("matches")?;Ok(self.matched)}fn latest(&mut self)->Result<(),usize>{self.hit("latest")}fn write(&mut self)->Result<(),usize>{self.hit("write")}}
#[test]fn exact_order_every_error_cutoff(){let expected=vec!["ready","matches","latest","write"];for cut in 0..=4{let mut p=Probe{trace:vec![],cut,matched:true};assert_eq!(execute(&mut p),if cut==0{Ok(true)}else{Err(Error::Callback(cut))});assert_eq!(p.trace,expected[..if cut==0{4}else{cut}]);}}
#[test]fn mismatch_stops_before_latest_or_effect(){let mut p=Probe{trace:vec![],cut:0,matched:false};assert_eq!(execute(&mut p),Ok(false));assert_eq!(p.trace,vec!["ready","matches"]);}}
